 const bg = el => { let e=el; while(e){ const c=getComputedStyle(e).backgroundColor; if(c && !/rgba\(0, 0, 0, 0\)|transparent/.test(c)) return c; e=e.parentElement;} return 'rgb(255,255,255)'; };
 const out=[];
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 const seen=new Set();
 while(walker.nextNode()){ const t=walker.currentNode; if(!t.textContent.trim()) continue; const el=t.parentElement; if(seen.has(el)) continue; seen.add(el); const r=el.getBoundingClientRect(); if(!r.width) continue; const cs=getComputedStyle(el); if(cs.visibility==='hidden') continue; const fg=cs.color, b=bg(el); const L1=lum(fg).L, L2=lum(b).L; const cr=(Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05); if(cr<4.6) out.push({tag:el.tagName, cls:el.className, txt:t.textContent.trim().slice(0,30), fg, b, cr:cr.toFixed(2), fs:cs.fontSize, fw:cs.fontWeight, op:cs.opacity}); }
