 document.querySelectorAll('input[placeholder]').forEach(i=>{const cs=getComputedStyle(i,'::placeholder'); out.push({ph:i.id, color:cs.color, bg:bg(i), op:cs.opacity, fs:cs.fontSize});});
 return out;
}"}

