  const walk=rs=>{for(const r of rs){ if(r.cssRules) walk(r.cssRules); if(!r.selectorText) continue; const t=r.cssText; if(/204, 204, 204|#ccc\b|focus|outline/i.test(t) && /radio|checkbox|focus|upload|page|crumb|skiplink/.test(r.selectorText)) out.push((sh.href||'inline').split('/').pop()+' :: '+t.slice(0,300)); }};
